SELECT store_id, CASE WHEN quantity >= 190 THEN 'PREMIUM' ELSE 'STANDARD' END AS quantity_tier, AVG(quantity) AS avg_quantity, ROUND(AVG(quantity), 2) AS avg_quantity_2, BIT_OR(quantity) AS quantity_bit_or, COUNT(*) AS num_rows FROM inventory GROUP BY GROUPING SETS ((store_id, CASE WHEN quantity >= 190 THEN 'PREMIUM' ELSE 'STANDARD' END), (store_id), ()) ORDER BY quantity_tier DESC;
